(function(){function render(item,hooks={}){if(item?.props?.scenario!=='phys.5.condensed.transition')return null;const root=document.createElement('section');root.className='card physics-condensed-lab';let disposed=false,mounted=false;const disposers=[];root.innerHTML="<h3>When the superconducting state ends</h3><p>Ideal bulk type-I teaching model: negligible demagnetization, fixed Tc = 7.2 K and \u03bc\u2080Hc(0) = 80 mT. This is not a microscopic prediction for a real specimen.</p><label>Temperature (K) <input data-condensed-role=\"temperature\" type=\"number\" min=\"0\" max=\"10\" step=\"0.1\" value=\"5\"></label><label>Applied \u03bc\u2080Ha (mT) <input data-condensed-role=\"field\" type=\"number\" min=\"0\" max=\"100\" step=\"1\" value=\"30\"></label><button data-condensed-role=\"boundary\">Inspect transition</button> <button data-condensed-role=\"reset\">Reset</button><p>Scroll the plot horizontally to inspect the full 0\u201310 K range. \u201cInspect transition\u201d centers the boundary when it exists.</p><div class=\"plot\" tabindex=\"0\" role=\"region\" aria-label=\"Temperature plot; scroll horizontally to inspect the full range\"><svg data-condensed-role=\"chart\" viewBox=\"0 0 800 440\" role=\"img\" aria-label=\"Separate superconducting and normal branches against temperature in kelvin\"></svg></div><p data-condensed-role=\"readout\" aria-live=\"polite\"></p><p>The gold branch ends at its superconducting one-sided limit. The blue branch is the normal state. Open endpoints at nonzero field indicate coexistence; no sloped line joins the jump and no unique homogeneous order is assigned at that point. The order index \u221a(1\u2212T/Tc) is phenomenological, not a measured energy gap. Finite-sample intermediate domains, surface barriers, hysteresis and type-II vortices are not solved.</p><h2>Longitudinal field and screening current</h2><p>Transparent wireframe of a displayed segment of an ideal infinite cylinder. Rings mark the viewing window, not physical ends. Blue arrows: B at 10 mm/T display scale. Gold arrows: surface K at 10\u207b\u2075 mm per A/m. White dots: zero-valued samples. Glyphs are not particle paths.</p><button data-condensed-role=\"turn-field\">Rotate field view</button> <button data-condensed-role=\"tilt-field\">Tilt field view</button> <button data-condensed-role=\"reset-field\">Reset field view</button><svg data-condensed-role=\"fieldplot\" viewBox=\"0 0 800 440\" style=\"min-width:0\" role=\"img\" aria-label=\"Three-dimensional ideal-cylinder field samples\"></svg><p data-condensed-role=\"field-status\"></p><p>The Gibbs-energy comparison uses \u0394g = (\u03bc\u2080Ha\u00b2 \u2212 \u03bc\u2080Hc\u00b2)/2, equivalently [(\u03bc\u2080Ha)\u00b2\u2212(\u03bc\u2080Hc)\u00b2]/(2\u03bc\u2080), below Tc. Negative favors the superconducting branch. The approximation \u03bc\u2080 \u2248 4\u03c0 \u00d7 10\u207b\u2077 H/m is used. There is no superconducting-branch energy supplied above Tc.</p>";const get=key=>root.querySelector('[data-condensed-role="'+key+'"]');
const state={temperature:5,appliedMilliTesla:30},chart=get('chart'),NS='http://www.w3.org/2000/svg';function el(tag,attrs,text){const e=document.createElementNS(NS,tag);for(const[k,v]of Object.entries(attrs))e.setAttribute(k,v);if(text!==undefined)e.textContent=text;chart.append(e);return e;}function draw(){if(disposed)return;const m=CondensedCore.build(state),X=t=>70+660*t/10,Y=q=>370-300*q;chart.replaceChildren();for(let i=0;i<=5;i++){el('text',{x:X(i*2),y:395,'text-anchor':'middle'},i*2);el('line',{x1:70,x2:730,y1:Y(i/5),y2:Y(i/5),stroke:'#34435b'});el('text',{x:60,y:Y(i/5)+5,'text-anchor':'end'},(i/5).toFixed(1));}el('text',{x:400,y:425,'text-anchor':'middle'},'Temperature (K)');el('text',{x:15,y:210,transform:'rotate(-90 15 210)','text-anchor':'middle'},'Phenomenological order index');for(const branch of m.branches){const color=branch.kind==='normal'?'#60b5ff':'#f4c35b';el('polyline',{points:branch.points.map(p=>X(p[0])+','+Y(p[1])).join(' '),fill:'none',stroke:color,'stroke-width':3,'data-branch':branch.kind});const point=branch.endOpen?branch.points.at(-1):branch.startOpen?branch.points[0]:null;if(point)el('circle',{cx:X(point[0]),cy:Y(point[1]),r:5,fill:'#101827',stroke:color,'stroke-width':2,'data-open-end':branch.kind});}if(m.transitionTemperatureK!==null)el('line',{x1:X(m.transitionTemperatureK),x2:X(m.transitionTemperatureK),y1:55,y2:370,stroke:'#b5a6c8','stroke-dasharray':'4 5','data-boundary':m.transitionTemperatureK});if(m.orderParameterIndex!==null)el('circle',{cx:X(m.temperature),cy:Y(m.orderParameterIndex),r:4,fill:'white','data-selected':'true'});get('readout').textContent=`At ${m.temperature.toPrecision(6)} K and μ₀Ha = ${m.appliedMilliTesla} mT: ${m.boundary&&m.appliedMilliTesla>0?'coexistence boundary; no unique homogeneous order index':m.superconducting?'superconducting branch':'normal state'}. ${m.gibbsDifferenceJPerM3===null?'Superconducting Gibbs branch unavailable at or above Tc.':'Δg = '+m.gibbsDifferenceJPerM3.toPrecision(6)+' J/m³.'}`;get('boundary').disabled=m.transitionTemperatureK===null;root.condensedReview=m;}for(const[id,key,max]of [['temperature','temperature',10],['field','appliedMilliTesla',100]])get(id).onchange=e=>{const v=e.target.valueAsNumber;if(!Number.isFinite(v)||v<0||v>max){e.target.value=state[key];return;}state[key]=v;draw();};get('boundary').onclick=()=>{const t=CondensedCore.build(state).transitionTemperatureK;if(t!==null){state.temperature=t;get('temperature').value=t;draw();const viewport=root.querySelector('.plot'),scale=chart.getBoundingClientRect().width/800;viewport.scrollLeft=Math.max(0,(70+660*t/10)*scale-viewport.clientWidth/2);}};get('reset').onclick=()=>{Object.assign(state,{temperature:5,appliedMilliTesla:30});get('temperature').value=5;get('field').value=30;draw();};draw();
(()=>{const plot=get('fieldplot'),status=get('field-status'),ns='http://www.w3.org/2000/svg';let yaw=.5,pitch=.45;function project(p){const x=Math.cos(yaw)*p[0]-Math.sin(yaw)*p[1],y=Math.sin(yaw)*p[0]+Math.cos(yaw)*p[1];return[400+70*x,220-70*(Math.cos(pitch)*p[2]-Math.sin(pitch)*y)];}function mark(tag,attrs){const e=document.createElementNS(ns,tag);for(const[k,v]of Object.entries(attrs))e.setAttribute(k,v);plot.append(e);return e;}function line(a,b,color,width=2,extra={}){const p=project(a),q=project(b);return mark('line',{x1:p[0],y1:p[1],x2:q[0],y2:q[1],stroke:color,'stroke-width':width,...extra});}function draw(){if(disposed)return;const model=CondensedGeometry.geometry(root.condensedReview);plot.replaceChildren();for(const ring of model.rings)for(let i=1;i<ring.length;i++)line(ring[i-1],ring[i],'#8798b4',1);for(let i=0;i<8;i++){const t=i*Math.PI/4;line([Math.cos(t),Math.sin(t),-2],[Math.cos(t),Math.sin(t),2],'#8798b4',1);}for(const g of [...model.fieldGlyphs,...model.currentGlyphs]){const p=project(g.originMM),q=project(g.endpointMM),color=g.kind==='surface-K'?'#f4c35b':'#60b5ff';if(g.zero){mark('circle',{cx:p[0],cy:p[1],r:2,fill:'#ddd','data-zero-kind':g.kind});continue;}const shaft=line(g.originMM,g.endpointMM,color,2,{'data-glyph-kind':g.kind});shaft.dataset.source=JSON.stringify(g);const dx=q[0]-p[0],dy=q[1]-p[1],length=Math.hypot(dx,dy);if(length>1e-8){const head=Math.min(7,length*.3),ux=dx/length,uy=dy/length;mark('path',{d:`M ${q[0]-head*ux-head*.45*uy} ${q[1]-head*uy+head*.45*ux} L ${q[0]} ${q[1]} L ${q[0]-head*ux+head*.45*uy} ${q[1]-head*uy-head*.45*ux}`,stroke:color,fill:'none','stroke-width':2});}}mark('line',{x1:50,y1:400,x2:120,y2:400,stroke:'white','stroke-width':3});const label=mark('text',{x:50,y:385,fill:'white',style:'font:'+(14*800/Math.max(1,plot.clientWidth))+'px system-ui'});label.textContent='1 mm';status.textContent=model.uniqueHomogeneousState?'Same spatial scale on all axes. Field and current glyphs use the separately declared value scales.':model.note;root.condensedFieldReview={model,yaw,pitch,spatialGain:70};}for(const id of ['temperature','field'])get(id).addEventListener('change',draw);for(const id of ['boundary','reset'])get(id).addEventListener('click',draw);get('turn-field').onclick=()=>{yaw+=.3;draw();};get('tilt-field').onclick=()=>{pitch+=.25;if(pitch>1.2)pitch=.2;draw();};get('reset-field').onclick=()=>{yaw=.5;pitch=.45;draw();};const resizeObserver=new ResizeObserver(draw);resizeObserver.observe(plot);disposers.push(()=>resizeObserver.disconnect());draw();})();

root.getModelSpeech=()=>[...root.querySelectorAll('p')].map(p=>p.textContent).join(' ');if(hooks.speakButton)root.querySelector('h3').prepend(hooks.speakButton(root.getModelSpeech,'Read this transition activity aloud'));root.dispose=()=>{if(disposed)return;disposed=true;for(const f of disposers)f();root.dataset.disposed='true';};const lifecycle=new MutationObserver(()=>{if(root.isConnected)mounted=true;else if(mounted)root.dispose();});lifecycle.observe(document,{childList:true,subtree:true});disposers.push(()=>lifecycle.disconnect());return root;}window.PrimerCondensedLab={render};})();